/**
 * @jest-environment node
 *
 * Has-many eager loading (the N+1 fix) and column selection, including dotted
 * relation columns. Uses drizzle's pg-proxy driver so the SQL is really
 * generated by Drizzle and can be asserted, with rows served from memory.
 */

import { beforeEach, describe, expect, it } from "@jest/globals";
import { drizzle } from "drizzle-orm/pg-proxy";
import { integer, pgTable, serial, varchar } from "drizzle-orm/pg-core";
import { SqlBaseCrudService } from "../src/core/abstract/sql-base-crud.service";
import type { SqlCrudConfig } from "../src/core/interfaces/sql-crud-config.interface";

const countries = pgTable("countries", {
	id: serial("id").primaryKey(),
	name: varchar("name"),
	region_id: integer("region_id"),
});

const regions = pgTable("regions", {
	id: serial("id").primaryKey(),
	name: varchar("name"),
	code: varchar("code"),
});

const states = pgTable("states", {
	id: serial("id").primaryKey(),
	name: varchar("name"),
	country_id: integer("country_id"),
});

class CountriesSvc extends SqlBaseCrudService<any, any, any, any> {}

// Serves each query from `rows` in call order and records the SQL. pg-proxy
// hands back raw value arrays, so a response is written positionally.
function proxyDb(responses: any[][][]) {
	const queries: Array<{ sql: string; params: any[] }> = [];
	let call = 0;
	const db = drizzle(async (sql, params) => {
		queries.push({ sql: sql.toLowerCase(), params });
		return { rows: responses[call++] ?? [] };
	});
	return { db, queries };
}

function makeService(
	db: any,
	overrides: Partial<SqlCrudConfig> = {},
): CountriesSvc {
	return new CountriesSvc({
		dialect: "postgresql",
		db,
		table: countries,
		primaryKey: "id",
		primaryKeyType: "serial",
		softDelete: { enabled: false, column: "deleted_at" },
		timestamps: undefined,
		pagination: { defaultLimit: 20, maxLimit: 100 },
		relations: {
			region: { table: regions, localKey: "region_id" },
			states: { table: states, type: "hasMany", foreignKey: "country_id" },
		},
		...overrides,
	});
}

describe("has-many eager loading", () => {
	it("loads children for a whole page in ONE extra query (no N+1)", async () => {
		const { db, queries } = proxyDb([
			// data query: three countries
			[
				[1, "India", 3],
				[2, "Nepal", 3],
				[3, "Chad", 4],
			],
			// count query
			[[3]],
			// the single batched children query
			[
				[10, "Karnataka", 1],
				[11, "Kerala", 1],
				[12, "Bagmati", 2],
			],
		]);
		const svc = makeService(db);

		const result = await svc.findAll({}, undefined, { relations: ["states"] });

		// data + count + one children query, for any number of parent rows.
		expect(queries).toHaveLength(3);
		const children = queries[2]!;
		expect(children.sql).toContain('from "states"');
		expect(children.sql).toContain("in (");
		expect(children.params).toEqual([1, 2, 3]);

		expect(result.data[0].states.map((s: any) => s.name)).toEqual([
			"Karnataka",
			"Kerala",
		]);
		expect(result.data[1].states.map((s: any) => s.name)).toEqual(["Bagmati"]);
		// A parent with no children gets an empty array, never undefined.
		expect(result.data[2].states).toEqual([]);
	});

	it("never joins a has-many relation, so total stays correct", async () => {
		const { db, queries } = proxyDb([[[1, "India", 3]], [[1]], []]);
		const svc = makeService(db);

		const result = await svc.findAll({}, undefined, { relations: ["states"] });

		expect(queries[0]!.sql).not.toContain("left join");
		expect(result.total).toBe(1);
		expect(result.data[0].states).toEqual([]);
	});

	it("loads children on find() too", async () => {
		const { db, queries } = proxyDb([
			[[1, "India", 3]],
			[
				[10, "Karnataka", 1],
				[11, "Kerala", 1],
			],
		]);
		const svc = makeService(db);

		const country: any = await svc.find(1, { relations: ["states"] });

		expect(queries).toHaveLength(2);
		expect(country.states).toHaveLength(2);
	});

	it("skips the children query entirely when no rows matched", async () => {
		const { db, queries } = proxyDb([[]]);
		const svc = makeService(db);

		expect(await svc.find(999, { relations: ["states"] })).toBeNull();
		expect(queries).toHaveLength(1);
	});

	it("combines a joined belongs-to and a batched has-many", async () => {
		const { db, queries } = proxyDb([
			[[1, "India", 3, 3, "Asia", "AS"]],
			[[10, "Karnataka", 1]],
		]);
		const svc = makeService(db);

		const country: any = await svc.find(1, {
			relations: ["region", "states"],
		});

		expect(queries[0]!.sql).toContain("left join");
		expect(country.region).toEqual({ id: 3, name: "Asia", code: "AS" });
		expect(country.states).toHaveLength(1);
	});
});

describe("column selection", () => {
	it("selects only the requested base columns", async () => {
		const { db, queries } = proxyDb([[[1, "India"]], [[1]]]);
		const svc = makeService(db);

		await svc.findAll({}, undefined, { select: ["id", "name"] });

		expect(queries[0]!.sql).toContain('select "id", "name" from');
		expect(queries[0]!.sql).not.toContain("region_id");
	});

	it("narrows an eager-loaded relation with a dotted path", async () => {
		const { db, queries } = proxyDb([[[1, "India", "Asia"]], [[1]]]);
		const svc = makeService(db);

		const result = await svc.findAll({}, undefined, {
			relations: ["region"],
			select: ["id", "name", "region.name"],
		});

		const sql = queries[0]!.sql;
		expect(sql).toContain('"regions"."name"');
		expect(sql).not.toContain('"regions"."code"');
		expect(result.data[0]).toEqual({
			id: 1,
			name: "India",
			region: { name: "Asia" },
		});
	});

	it("narrows has-many children, keeping the key needed for grouping", async () => {
		const { db, queries } = proxyDb([
			[[1, "India"]],
			[[1]],
			[
				["Karnataka", 1],
				["Kerala", 1],
			],
		]);
		const svc = makeService(db);

		const result = await svc.findAll({}, undefined, {
			relations: ["states"],
			select: ["id", "name", "states.name"],
		});

		expect(queries[2]!.sql).toContain('select "name", "country_id" from');
		expect(result.data[0].states).toEqual([
			{ name: "Karnataka", country_id: 1 },
			{ name: "Kerala", country_id: 1 },
		]);
	});

	it("keeps the parent key in the projection when only other columns are asked for", async () => {
		const { db, queries } = proxyDb([[["India", 1]], [[1]], []]);
		const svc = makeService(db);

		await svc.findAll({}, undefined, {
			relations: ["states"],
			select: ["name"],
		});

		// "id" was not requested but is required to group the children.
		expect(queries[0]!.sql).toContain('select "name", "id" from');
	});

	it("returns the whole parent row when only relation columns are selected", async () => {
		const { db, queries } = proxyDb([[[1, "India", 3, "Asia"]], [[1]]]);
		const svc = makeService(db);

		await svc.findAll({}, undefined, {
			relations: ["region"],
			select: ["region.name"],
		});

		expect(queries[0]!.sql).toContain('"countries"."region_id"');
	});
});

describe("has-many filtering", () => {
	it("filters parents by a child column with a subquery, not a join", async () => {
		const { db, queries } = proxyDb([[[1, "India", 3]], [[1]]]);
		const svc = makeService(db);

		await svc.findAll({ states: { name: "Kerala" } });

		const sql = queries[0]!.sql;
		expect(sql).toContain("in (select");
		expect(sql).toContain('from "states"');
		expect(sql).not.toContain("left join");
		// The same predicate has to reach the count query, or total lies.
		expect(queries[1]!.sql).toContain("in (select");
	});

	it("ignores a has-many filter with no usable columns", async () => {
		const { db, queries } = proxyDb([[], [[0]]]);
		const svc = makeService(db);

		await svc.findAll({ states: { nope: "x" } });

		expect(queries[0]!.sql).not.toContain("select 1");
		expect(queries[0]!.sql).not.toContain("in (select");
	});
});

describe("relation config validation", () => {
	let db: any;

	beforeEach(() => {
		db = proxyDb([]).db;
	});

	it("rejects a has-many relation without a foreignKey", () => {
		expect(() =>
			makeService(db, {
				relations: { states: { table: states, type: "hasMany" } },
			}),
		).toThrow(/requires a foreignKey/);
	});

	it("rejects a belongs-to relation without a localKey", () => {
		expect(() =>
			makeService(db, { relations: { region: { table: regions } } }),
		).toThrow(/requires a localKey/);
	});
});
